import math

def get_divisors(n):
    divisors = set()
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

def solve():
    a, b = map(int, input().split())
    g = math.gcd(a, b)
    divisors = get_divisors(g)

    n = int(input())
    for _ in range(n):
        low, high = map(int, input().split())
        found = -1
        for d in divisors:
            if low <= d <= high:
                found = d
        print(found)

solve()
"}

