import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    n, b = int(data[0]), int(data[1])
    a = list(map(int, data[2:2+n]))
    sum_a = sum(a)
    total = b + sum_a
    x = total / n
    res = [x - ai for ai in a]
    if any(r < 0 for r in res):
        print(-1)
    else:
        for num in res:
            print(f"{num:.6f}")

if __name__ == "__main__":
    solve()
"}

