            # Need to change chars[i]
            # Choose a character different from chars[i-1] and also from chars[i+1] if exists
            # Loop over 26 letters
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c != chars[i - 1] and (i + 1 == n or c != chars[i + 1]):
                    chars[i] = c
                    break

    print(''.join(chars))

solve()
