# If m is already larger than n, we need to work backwards
if m > n:
    operations = 0
    # Work backwards from m to n
    while m > n:
        if m % 2 == 0:
            # Could have come from m/2 via multiplication
            m //= 2
        else:
            # Could have come from m+1 via subtraction
            m += 1
        operations += 1
    # Now m == n, so we need to subtract (n - m) times (which is 0)
    print(operations)
else:
    # m is less than or equal to n, we just need to subtract
    print(n - m)
