import sys

def solve() -> None:
    s = sys.stdin.readline().strip()
    n = len(s)

    # If the string is already simple, return it
    if all(s[i] != s[i+1] for i in range(n-1)):
        print(s)
        return

    # Traverse the string and change every other character
    # in each run starting from the second character
    i = 0
    while i < n:
        # Find the start of a run
        start = i
        while i + 1 < n and s[i+1] == s[i]:
            i += 1

        # We have a run from start to i (inclusive)
        # Change every other character starting from the second one in the run
        for j in range(start + 1, i + 1, 2):
            # Change s[j] to something else
            # Choose a character that is not the same as the character before or after
            if j == n - 1:
                # No character after, just change to something different
                # Choose 'a' if not the same as previous character
                if s[j-1] == 'a':
                    new_char = 'b'
                else:
                    new_char = 'a'
            else:
                # No character before, just change to something different
                if s[j+1] == 'a':
                    new_char = 'b'
                else:
                    new_char = 'a'

            s = s[:j] + new_char + s[j+1:] if j == n-1 else s[:j] + new_char + s[j+1:]

        i += 1

    print(s)

solve()
