    if gcd_value == 0:
        return -1

    # If the GCD is already in range
    if low <= gcd_value <= high:
        return gcd_value

    # If the range is entirely above the GCD, no divisor exists
    if high < gcd_value:
        return -1

    # Otherwise, we need to find the largest divisor of gcd_value
    # that is <= high

    # Check from high down to low
    for i in range(min(high, gcd_value), 0, -1):
        if gcd_value % i == 0 and i >= low:
            return i

    return -1


