def gcd(x, y):
    while y:
        x, y = y, x % y
    return x


def find_divisors(x):
    divisors = set()
    for i in range(1, int(x**0.5) + 1):
        if x % i == 0:
            divisors.add(i)
            divisors.add(x // i)
    return sorted(divisors)

def max_divisor_in_range(divisors, low, high):
    if not divisors:
        return -1

    # Use binary search to find the largest divisor <= high
    # We can also iterate from high down to low

    # Simple iteration from high down to low
    for i in range(high, 0, -1):
        if i in divisors and i >= low:
            return i

    return -1


