import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    m = int(data[0])
    n = int(data[1])
    a = list(map(int, data[2:2+n]))

    # We need to find x and d such that {x, x+d, x+2d, ..., x+(n-1)d} mod m equals the set of elements
    elements = set(a)

    # Try each element as the first element x
    for x in a:
        # Try each other element as a potential next element to determine difference d
        for i in range(n):
            if a[i] == x:
                continue
            # Calculate difference d
            d = (a[i] - x) % m

            # Check if this difference works
            found = True
            for k in range(n):
                expected = (x + k * d) % m
                if expected not in elements:
                    found = False
                    break

            if found:
                print(x, d)
                return

    print(-1)

if __name__ == "__main__":
    solve()
