n = int(input())
a = list(map(int, input().split()))

# Check if any duplicates exist at all
seen = set()
duplicate_indices = []
for i, num in enumerate(a):
    if num in seen:
        duplicate_indices.append(i)
    else:
        seen.add(num)

if not duplicate_indices:
    print(-1)
else:
    # Greedily find segments from left to right
    result = []
    used = set()
    start = 0

    for i, num in enumerate(a):
        if num in used:
            # End current segment at this position
            result.append((start + 1, i + 1))
            start = i + 1
            used = set([num])
        else:
            used.add(num)

    # Check if the last segment is valid (has at least one duplicate)
    if len(result) == 0:
        # No segment found, should never happen if duplicate_indices is non-empty
        print(-1)
    else:
        if start < n:
            # Check if the last segment (from start to end) has a duplicate
            # Find if there's a duplicate in the range [start, n-1]
            last_used = set()
            duplicate_in_last = False
            for j in range(start, n):
                if a[j] in last_used:
                    duplicate_in_last = True
                    break
                last_used.add(a[j])

    if duplicate_in_last:
        print(len(result))
        for l, r in result:
            print(l, r)
    else:
        print(-1)
