from collections import Counter

def get_mask(s):
    """Return a 26-bit mask representing parity of character counts"""
    mask = 0
    for c in s:
        mask ^= 1 << ord(c) - ord('a')
    return mask

def palindrome_pairs(strings):
    masks = []
    for s in strings:
        masks.append(get_mask(s))

    cnt = Counter(masks)
    total = 0

    # Count pairs with same mask
    for mask, freq in cnt.items():
        total += freq * (freq - 1) // 2

    # Count pairs that differ by exactly one bit
    # For each mask, check other masks that differ by exactly one bit
    for mask, freq in cnt.items():
        # Try flipping each bit
        for i in range(26):
            diff_mask = mask ^ (1 << i)
            if diff_mask in cnt:
                total += freq * cnt[diff_mask]

    return total

if __name__ == "__main__":
    import sys

    strings = []
    for line in sys.stdin:
        s = line.strip()
        if s:
            strings.append(s)

    print(palindrome_pairs(strings))
"}

