import math

def solve() -> None:
    # Read input
    a, b = map(int, input().split())

    # Find least common multiple
    lcm = a * b // math.gcd(a, b)

    # Count time intervals
    dasha_time = 0
    masha_time = 0

    # List of all event times
    events = []
    for i in range(1, lcm // a + 1):
        events.append((i * a, 'Dasha'))
    for i in range(1, lcm // b + 1):
        events.append((i * b, 'Masha'))

    # Sort events by time
    events.sort()

    # Add the starting time 0
    events.append((0, 'Start'))

    # Track which train arrives next
    last_train = None
    next_dasha = 0
    next_masha = 0

    # Initial state: No trains have arrived yet
    for i in range(lcm // a + 1):
        next_dasha = i * a
    for i in range(lcm // b + 1):
        next_masha = i * b

    # Process events
    prev_time = 0
    for time, _ in events:
        # Determine which train arrives next at this point
        if prev_time < next_dasha and prev_time < next_masha:
            # No train arrives yet, this is the Start event
            # Determine which train arrives first
            # If next_dasha <= next_masha, Dasha first, else Masha first
            if next_dasha <= next_masha:
                dasha_time += time - prev_time
            else:
                masha_time += time - prev_time
        elif prev_time >= next_dasha and prev_time < next_masha:
            # Dasha train arrived
            # Determine which train arrives first from this point
            if next_dasha <= next_masha:
                dasha_time += time - prev_time
            else:
                masha_time += time - prev_time
        elif prev_time < next_dasha and prev_time >= next_masha:
            # Masha train arrived
            if next_dasha <= next_masha:
                dasha_time += time - prev_time
            else:
                masha_time += time - prev_time
        elif prev_time >= next_dasha and prev_time >= next_masha:
            # Both trains arrived
            # Tie rule: go to direction with less frequent trains
            if a <= b:
                dasha_time += time - prev_time
            else:
                masha_time += time - prev_time

        # Update next event times
        if next_dasha == prev_time:
            next_dasha = next_dasha + a
        if next_masha == prev_time:
            next_masha = next_masha + b

        prev_time = time

    # Output result
    if dasha_time > masha_time:
        print("Dasha")
    elif dasha_time < masha_time:
        print("Masha")
    else:
        print("Equal")

