import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    adj = [[] for _ in range(n + 1)]

    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)

    # Find cycles using DFS
    visited = [False] * (n + 1)
    cycles = []

    def dfs(u, parent, path):
        visited[u] = True
        path.append(u)

        for v in adj[u]:
            if v == parent:
                continue
            if not visited[v]:
                dfs(v, u, path)
            elif v == path[0]:
                # Found a cycle
                cycle = path[1:]  # Skip the start node
                cycle.append(v)
                cycles.append(cycle)
                path.pop()
                return

        path.pop()

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, -1, [])

    # Count how many cycles each node belongs to
    cycle_count = [0] * (n + 1)

    for cycle in cycles:
        for node in cycle:
            cycle_count[node] += 1

    k = int(next(it))

    output = []
    for _ in range(k):
        x = int(next(it))
        y = int(next(it))

        # If they are in the same cycle
        if cycle_count[x] > 0 and cycle_count[y] > 0 and cycle_count[x] == cycle_count[y]:
            output.append(2)
        else:
            output.append(1)

    sys.stdout.write("\n".join(map(str, output)))

if __name__ == "__main__":
    main()
