import sys

def solve()
    n = int(sys.stdin.readline())
    p = list(map(int, sys.stdin.readline().split()))
    t_line = sys.stdin.readline().split()
    t = int(t_line[0]) if t_line else 0
    q = [int(qi) - 1 for qi in t_line[1:]] if t else []

    # Try to reconstruct x
    x = [0] * n

    # Process all negative positions
    for idx in q:
        # This position is negative, so x[idx] = -p[idx]
        x[idx] = -p[idx]

    # Process remaining positive positions
    for idx in range(n):
        if idx not in q:
            # This position is positive, so x[idx] = p[idx]
            x[idx] = p[idx]

    # Check if this forms a valid sequence
    # We need to check if the sequence is a correct bracket sequence
    # I'll use a simple balance check
    balance = {}
    for i, val in enumerate(x):
        if val > 0:
            # This is an opening bracket
            if val in balance:
                balance[val] += 1
            else:
                balance[val] = 1
        else:
            # This is a closing bracket
            if val in balance and balance[val] > 0:
                balance[val] -= 1
            else:
                # Doesn't match, invalid
                return "NO"

    # Check if all balances are zero
    for cnt in balance.values():
        if cnt != 0:
            return "NO"

    return "YES\n" + " ".join(map(str, x))

def main():
    result = solve()
    if result == "NO":
        print("NO")
    else:
        print(result)

if __name__ == "__main__":
    main()
