def solve():
    n, p = map(int, input().split())

    # We need to find the minimum k such that:
    # n = sum_{i=1}^k (2^xi + p)
    # => n - kp = sum_{i=1}^k 2^xi

    for k in range(1, 40):  # Check reasonable k values
        target = n - k * p
        if target <= 0:
            continue

        if k == 1:
            # Must be a single power of 2
            if (target & (target - 1)) == 0:
                return k
        else:
            # Must have at least k bits set
            if bin(target).count('1') >= k:
                return k

    return -1

