{"code": "import sys
from math import gcd

def extended_gcd(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        g, x, y = extended_gcd(b, a % b)
        return (g, y, x - (a // b) * y)

def mod_inverse(a, m):
    g, x, y = extended_gcd(a, m)
    if g != 1:
        return None  # No inverse exists
    else:
        return x % m


def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    m = int(data[0])
    n = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Try each element as the first element of the progression
    for i in range(n):
        x = a[i]
        seen = {a[j]: True for j in range(n)}

        # Try each other element as the (k+1)-th element for some k
        for j in range(n):
            if i == j:
                continue
            y = a[j]
            k = j - i  # k-th element after x
            if k < 1 or k >= n:
                continue

            # Check if (y - x) is divisible by k modulo m
            diff = (y - x) % m
            inv_k = mod_inverse(k, m)
            if inv_k is None:
                continue

            d = (diff * inv_k) % m

            # Check if we can form a valid progression
            valid = True
            for l in range(n):
                expected = (x + d * l) % m
                if expected != a[l]:
                    valid = False
                    break

            if valid:
                print(x, d)
                return

    print(-1)

solve()
