def calculate_probability(friends):
    n = len(friends)
    if n == 0:
        return 0.0

    # Check all subsets of friends
    max_prob = 0.0

    # Try all subsets of friends (excluding empty set)
    for mask in range(1, 1 << n):
        subset = [friends[i] for i in range(n) if (mask & (1 << i))]
        k = len(subset)
        if k == 0:
            continue

        # Probability of exactly one success
        prob = 0.0
        for i in range(k):
            # ith friend succeeds, others fail
            success = subset[i]
            failure = 1.0 - success
            for j in range(k):
                if j != i:
                    failure *= (1.0 - subset[j])
            prob += success * failure

        if prob > max_prob:
            max_prob = prob

    return max_prob

