import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Find the number of unique values
        unique_vals = set(a)
        num_unique = len(unique_vals)

        # Determine minimum size
        if num_unique == 1:
            # All elements are the same; we can't remove any
            min_size = n % 2
        else:
            # We can remove all but possibly 1
            if n % 2 == 0:
                min_size = 0
            else:
                min_size = 1

        out_lines.append(str(min_size))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
