import sys

def bfs(grid, i, j, n, m, visited, land_cells):
    if i < 0 or i >= n or j < 0 or j >= m or visited[i][j] or grid[i][j] == '*':
        return
    visited[i][j] = True
    land_cells.append((i, j))
    for dx, dy in [(0,1),(1,0),(0,-1),(-1,0)]:
        bfs(grid, i+dx, j+dy, n, m, visited, land_cells)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))
    grid = []
    for _ in range(n):
        grid.append(list(next(it)))
    visited = [[False]*m for _ in range(n)]
    lakes = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j] and (i not in [0, n-1] or j not in [0, m-1]):
                land_cells = []
                bfs(grid, i, j, n, m, visited, land_cells)
                if not land_cells:
                    continue
                # Check if this lake touches border
                touches_border = False
                for (x, y) in land_cells:
                    if x in (0, n-1) or y in (0, m-1):
                        touches_border = True
                        break
                if not touches_border:
                    lakes.append(land_cells)
    # Sort lakes by area descending
    lakes.sort(key=lambda x: -len(x))
    # We need exactly k lakes. So fill lakes[total_lakes - k:].
    # But we must ensure no merge issues, just fill any.
    filled = set()
    total = 0
    for i in range(len(lakes) - k):
        lake = lakes[i]
        for (x, y) in lake:
            filled.add((x, y))
            total += 1
    # Construct result grid
    result = [list(row) for row in grid]
    for (i, j) in filled:
        result[i][j] = '*'
    print(total)
    for row in result:
        print(''.join(row))

if __name__ == '__main__':
    main()
"}

