                touches_border = False
                for (x, y) in land_cells:
                    if x == 0 or x == n-1 or y == 0 or y == m-1:
                        touches_border = True
                        break
                if not touches_border:
                    lakes.append(land_cells)
    # Sort lakes by area descending
    lakes.sort(key=lambda x: -len(x))
    # Need to fill lakes[total_lakes - k : ]
    total_lakes = len(lakes)
    filled = set()
    total = 0
    for lake in lakes[total_lakes - k:]:
        for (x, y) in lake:
            filled.add((x, y))
            total += 1
    # Construct result grid
    result = [list(row) for row in grid]
    for (i, j) in filled:
        result[i][j] = '*'
    print(total)
    for row in result:
        print(''.join(row))

