import sys

def solve() -> None:
    # Read input
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    ops = data[1]
    x = int(data[2])
    y = int(data[3])

    # Calculate total displacement
    total_dx = 0
    total_dy = 0
    for op in ops:
        if op == 'U':
            total_dy += 1
        elif op == 'D':
            total_dy -= 1
        elif op == 'L':
            total_dx -= 1
        elif op == 'R':
            total_dx += 1

    # If already at target, no changes needed
    if total_dx == x and total_dy == y:
        print(0)
        return

    # Try all possible subsegments to change
    min_len = -1

    # For each possible length of subsegment to change
    for length in range(1, n + 1):
        # Try all possible starting positions
        for start in range(n - length + 1):
            # End position of the subsegment
            end = start + length - 1

            # Calculate the displacement of the unchanged parts
            # Displacement from operations before the subsegment
            dx_left = 0
            dy_left = 0
            for i in range(start):
                op = ops[i]
                if op == 'U':
                    dy_left += 1
                elif op == 'D':
                    dy_left -= 1
                elif op == 'L':
                    dx_left -= 1
                elif op == 'R':
                    dx_left += 1

            # Displacement from operations after the subsegment
            dx_right = 0
            dy_right = 0
            for i in range(end + 1, n):
                op = ops[i]
                if op == 'U':
                    dy_right += 1
                elif op == 'D':
                    dy_right -= 1
                elif op == 'L':
                    dx_right -= 1
                elif op == 'R':
                    dx_right += 1

            # Total displacement from unchanged parts
            total_unchanged = (dx_left + dx_right, dy_left + dy_right)

            # Required displacement from the changed subsegment
            req_dx = x - total_unchanged[0]
            req_dy = y - total_unchanged[1]

            # Check if this can be achieved with a subsegment of this length
            # For length L, we need |req_dx| + |req_dy| <= length
            if abs(req_dx) + abs(req_dy) <= length:
                min_len = length
                break
        if min_len != -1:
            break

    print(min_len if min_len != -1 else -1)

if __name__ == "__main__":
    solve()
