import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return
    lines = data
    n = int(lines[0])
    forbidden = lines[1:n+1]
    w = lines[n+1]
    lucky_letter = lines[n+2].strip().lower()

    len_w = len(w)

    # Build a set of intervals (1-indexed) where forbidden substring matches
    covered = set()  # positions 1..len_w

    # For each forbidden substring
    for s in forbidden:
        s_len = len(s)
        if s_len > len_w:
            continue
        s_lower = s.lower()

        # Try all starting positions
        for start in range(len_w - s_len + 1):
            substr = w[start:start+s_len]
            substr_lower = substr.lower()
            if substr_lower == s_lower:
                end = start + s_len - 1
                for pos in range(start + 1, end + 1):
                    covered.add(pos)

    # Build result
    res = []
    lucky_upper = lucky_letter.upper()
    for i in range(len_w):
        pos = i + 1
        orig = w[i]
        if pos in covered:
            # Must replace
            if orig.islower() and orig != lucky_letter:
                res.append(lucky_letter)
            elif orig.isupper() and orig != lucky_upper:
                res.append(lucky_upper)
            else:
                # orig == lucky_letter (lower) or orig == lucky_upper (upper), cannot use lucky
                # pick smallest possible letter of same case that is not orig
                if orig.islower():
                    # try 'a' to 'z' except lucky_letter
                    for c in 'abcdefghijklmnopqrstuvwxyz':
