import sys
from collections import Counter

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    freq = Counter()
    for num in a:
        freq[num] += 1

    for v in freq:
        if freq[v] > 2:
            print("NO")
            return

    inc_set = []
    dec_set = []
    for num in freq:
        if freq[num] == 1:
            inc_set.append(num)
        elif freq[num] == 2:
            inc_set.append(num)
            dec_set.append(num)

    inc = sorted(inc_set)
    dec = sorted(dec_set, reverse=True)

    print("YES")
