def solve():
    n, m = map(int, input().split())

    # Read initial state
    initial = []
    for _ in range(n):
        initial.append(input().split())

    # Read final state
    final = []
    for _ in range(n):
        final.append(input().split())

    # Convert to lists of lists of characters
    initial_chars = [[list(s) for s in row] for row in initial]
    final_chars = [[list(s) for s in row] for row in final]

    # Check if we're already at the target
    if initial == final:
        print(0)
        return

    # Strategy: work row by row, left to right, then column by column

    operations = []

    # Build a target configuration we can achieve
    target_chars = [[row.copy() for row in final] for _ in range(n)]

    # For each row
    for i in range(n):
        # For each column in this row
        for j in range(m):
            # Get what the target has for this cell
            target_str = target_chars[i][j]

            # Get what we have
            current_str = initial_chars[i][j]

            # Work character by character, right to left
            for pos in range(len(target_str) - 1, -1, -1):
                needed_char = target_str[pos]

                # Find what we have at this position (considering what we've moved)
                have_char = current_str[pos] if pos < len(current_str) else None

                if needed_char == have_char:
                    continue

                # Find a source with this character
                found = False

                # Search in the same row
                for col in range(m):
                    if col == j:
                        continue
                    if initial_chars[i][col]:
                        if initial_chars[i][col][-1] == needed_char:
                            operations.append((i+1, col+1, i+1, j+1))
                            current_str.append(initial_chars[i][col].pop())
                            found = True
                            break

                if not found:
                    # Search in the same column
                    for row in range(n):
                        if row == i:
                            continue
                        if initial_chars[row][j]:
                            if initial_chars[row][j][-1] == needed_char:
                                operations.append((row+1, j+1, i+1, j+1))
                                current_str.append(initial_chars[row][j].pop())
                                found = True
                                break

                if not found:
                    # Search anywhere else
                    for r in range(n):
                        for c in range(m):
                            if r == i and c == j:
                                continue
                            if initial_chars[r][c] and initial_chars[r][c][-1] == needed_char:
                                operations.append((r+1, c+1, i+1, j+1))
                                current_str.append(initial_chars[r][c].pop())
                                found = True
                                break
                        if found:
                            break

    print(len(operations))
    for op in operations:
        print(f"{op[0]} {op[1]} {op[2]} {op[3]}")

