import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    q = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    results = []

    for _ in range(q):
        l = int(next(it)) - 1
        r = int(next(it)) - 1
        elements = a[l:r+1]

        pieces = []
        for elem in elements:
            # Try to add to current piece
            current = pieces[-1] if pieces else None
            if current is None:
                # Start a new piece
                pieces.append([elem])
            else:
                x = len(current)
                freq = {}
                for item in current:
                    freq[item] = freq.get(item, 0) + 1
                if freq.get(elem, 0) + 1 > (x // 2) + 1:
                    # Can't add to current piece, start a new one
                    pieces.append([elem])
                else:
                    current.append(elem)

        results.append(str(len(pieces)))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

