import sys

def solve():
    input = sys.stdin.read().split()
    if not input:
        return
    it = iter(input)
    t = int(next(it))
    results = []

    for _ in range(t):
        n = int(next(it))
        c = [int(next(it)) for _ in range(n)]
        freq = {}

        # Count frequencies of each category
        for cat in c:
            freq[cat] = freq.get(cat, 0) + 1

        # Get the counts of icons per category
        counts = list(freq.values())

        # Find the maximum count (upper bound for possible screen sizes)
        max_count = max(counts) if counts else 0

        # Try all possible screen sizes s from 1 to max_count
        # The optimal s will be somewhere in this range
        min_screens = float('inf')

        for s in range(1, max_count + 1):
            total = 0

            for cnt in counts:
                if cnt > s:
                    total += (cnt + s - 1) // s
                elif cnt < s - 1:
                    break
                else:
                    total += 1

            if total < min_screens:
                min_screens = total

        results.append(str(min_screens))

    sys.stdout.write('\n'.join(results))

