import sys

def is_typo(block):
    """Check if a block of consonants forms a typo."""
    if len(block) < 3:
        return False
    # Check if all consonants are the same
    if all(c == block[0] for c in block):
        return False
    # Check if there are at least 2 different consonants in the block
    if len(set(block)) <= 1:
        return False
    return True

def solve(word):
    n = len(word)
    result = []
    i = 0

    while i < n:
        # Find the next potential typo
        j = i
        # Track current block of consonants
        current_block = []

        while j < n:
            c = word[j]
            if c in {'a', 'e', 'i', 'o', 'u'}:
                # Vowel, end current block
                if current_block and len(current_block) >= 3:
                    # Check if this block is a typo
                    if is_typo(current_block):
                        # Split before the first consonant of this typo
                        # Start new segment after the second consonant of previous block
                        result.append(word[i:j])
                        # Move to after the second consonant of this block
                        # (we'll process from the third consonant)
                        i = j + 1
                        break
                i = j + 1
                break
            else:
                # Consonant, add to current block
                current_block.append(c)
                j += 1

        if j == n and current_block:
            # End of word, check if current block is a typo
            if is_typo(current_block):
                # Split before the first consonant of this typo
                result.append(word[i:j])
                i = j
            else:
                result.append(word[i:j])


    return ' '.join(result)

if __name__ == "__main__":
    word = sys.stdin.read().strip()
    print(solve(word))
"}

