    probs = [float(x) for x in input().split()]

    max_prob = 0.0

    # Try all subsets
    for mask in range(1 << n):
        # Instead of building the subset each time, we can compute it directly
        friends = [probs[i] for i in range(n) if mask & (1 << i)]

        prob = 0.0
        for i in range(len(friends)):
            p = friends[i]
            prob_i = p
            for j in range(len(friends)):
                if j != i:
                    prob_i *= (1.0 - friends[j])
            prob += prob_i

        max_prob = max(max_prob, prob)

    print(f"{max_prob:.10f}")

