import sys

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    cnt1, cnt2, x, y = map(int, data[:4])

    def is_ok(v: int) -> bool:
        a1 = v // x
        a2 = v // y
        a3 = v // (x * y)

        # Condition 1: enough not divisible by x
        if v - a1 < cnt1:
            return False

        # Condition 2: enough not divisible by y
        if v - a2 < cnt2:
            return False

        # Condition 3: not x only >= max(0, cnt1 - a3)
        if v - a1 - a3 < max(0, cnt1 - a3):
            return False

        # Condition 4: not y only >= max(0, cnt2 - a3)
        if v - a2 - a3 < max(0, cnt2 - a3):
            return False

        return True

    # Binary search
    left = 1
    right = 10000000000
    while left < right:
        mid = (left + right) // 2
        if is_ok(mid):
            right = mid
        else:
            left = mid + 1

    sys.stdout.write(str(left))

if __name__ == "__main__":
    solve()
"}

