import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Count occurrences of each value
        counts = {}  # counts[value] = count
        for num in a:
            counts[num] = counts.get(num, 0) + 1

        # Calculate minimum possible size
        # Option 1: if n even, min size 0; if n odd, min size 1
        # But this contradicts example 3
        # Option 2: if all counts even, min size 0; else min size 1 or 2?

        # Try option 2: if all counts even, min size 0
        # if at least one count odd, min size 2 if n odd, else 1
        if all(v % 2 == 0 for v in counts.values()):
            out_lines.append('0')
        else:
