    seen = set()
    found_duplicate = False

    for i in range(n):
        if a[i] in seen:
            segments.append((start + 1, i + 1))  # 1-indexed
            start = i + 1
            seen = set()
            seen.add(a[i])
            found_duplicate = True
            break
        else:
            seen.add(a[i])

    if not found_duplicate:
        # No more segments
        break

