    print(len(segments))
    for seg in segments:
        print(seg[0], seg[1])
else:
    # Check if the entire array has any duplicates
    if len(set(a)) < n:
        segments.append((1, n))
        print(len(segments))
        for seg in segments:
            print(seg[0], seg[1])
    else:
        print(-1)
