    low, high = map(int, input().split())

    # Find the largest divisor <= high
    left, right = 0, len(divisors) - 1
    answer = -1

    while left <= right:
        mid = (left + right) // 2
        if divisors[mid] <= high:
            answer = divisors[mid]
            left = mid + 1
        else:
            right = mid - 1

    # Check if the answer is >= low
    if answer >= low:
        print(answer)
    else:
        print(-1)
