import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    freq = {}
    for _ in range(n):
        s = next(it)
        mask = 0
        for c in s:
            mask ^= 1 << (ord(c) - ord('a'))
        freq[mask] = freq.get(mask, 0) + 1
    total = 0
    # same mask pairs
    for mask, cnt in freq.items():
        total += cnt * (cnt - 1) // 2
    # cross pairs
    for mask, cnt in freq.items():
        for i in range(26):
            if (mask & (1 << i)) == 0:
                neighbor = mask ^ (1 << i)
                if neighbor in freq:
                    total += cnt * freq[neighbor]
    print(total)

if __name__ == "__main__":
    main()
"}

