from collections import Counter

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    strings = data[1:]

    # Count frequency of each string
    freq = {}
    for s in strings:
        freq[s] = freq.get(s, 0) + 1

    result = 0

    # For each unique string, check all other unique strings
    keys = list(freq.keys())
    for i in range(len(keys)):
        s1 = keys[i]
        count1 = Counter(s1)
        freq1 = freq[s1]

        for j in range(i, len(keys)):
            s2 = keys[j]
            count2 = Counter(s2)
            freq2 = freq[s2]

            # Combine counts
            combined = Counter()
            for char, count in count1.items():
                combined[char] = count
            for char, count in count2.items():
                combined[char] += count

            L = len(s1) + len(s2)
            odd_count = sum(1 for count in combined.values() if count % 2 != 0)

            if (L % 2 == 0 and odd_count == 0) or (L % 2 == 1 and odd_count == 1):
                # This is a palindrome pair
                if i == j:
                    # Same string, count pairs: C(freq1, 2) = freq1 * (freq1 - 1) // 2
                    result += freq1 * (freq1 - 1) // 2
                else:
                    # Different strings, count pairs: freq1 * freq2
                    result += freq1 * freq2

    print(result)

if __name__ == "__main__":
    main()
"}

