def is_good(s):
    """Check if a string is good (becomes palindrome after merging consecutive equal characters)."""
    if not s:
        return False

    # Merge consecutive equal characters
    merged = []
    for char in s:
        if merged and merged[-1] == char:
            continue
        merged.append(char)

    # Check if merged string is a palindrome
    return merged == merged[::-1]

