import sys

def is_consonant(c):
    return c not in {'a', 'e', 'i', 'o', 'u'}

def has_typo(s):
    i = 0
    n = len(s)
    while i < n:
        j = i
        # Find the length of the current consonant block
        while j < n and is_consonant(s[j]):
            j += 1
        if j - i >= 3:
            # Check if all consonants are the same
            all_same = True
            for k in range(i, j):
                if s[k] != s[i]:
                    all_same = False
                    break
            if not all_same:
                return True
        i = j
    return False

def solve():
    s = sys.stdin.readline().strip()
    if not has_typo(s):
        print(s)
        return

    n = len(s)
    # dp[i] = minimum number of spaces needed for prefix ending at position i
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    # Reconstruct path
    prev = [-1] * (n + 1)

    for i in range(1, n + 1):
        # Try to split at position j (0 <= j < i)
        for j in range(i):
            if not has_typo(s[j:i]):
                if dp[j] + 1 < dp[i]:
                    dp[i] = dp[j] + 1
                    prev[i] = j

    # Reconstruct the solution
    if dp[n] == float('inf'):
        print(s)
    else:
        current = n
        result = []
        while current > 0:
            prev_pos = prev[current]
            result.append(s[prev_pos:current])
            current = prev_pos
        result.reverse()
        print(' '.join(result))

if __name__ == '__main__':
    solve()
"}

